-- Only small published result tables. No raw ODS/period joins. Current business month (yesterday); do not fall back to an older month.
WITH latest AS(SELECT report_month,MAX(data_as_of) data_as_of FROM dm_tmp.maxyu_id_long_monitor_publish WHERE report_month=CAST(DATE_TRUNC('month',DATE_SUB(CURRENT_DATE(),INTERVAL 1 DAY)) AS DATE) GROUP BY report_month),
ready AS(SELECT p.* FROM dm_tmp.maxyu_id_long_monitor_publish p JOIN latest l ON p.report_month=l.report_month AND p.data_as_of=l.data_as_of)
SELECT r.report_month,r.data_as_of,p.published_at,p.config_version,p.config_sha256,
r.`target_version`,r.`report_date`,r.`stage`,r.`mode`,r.`stage_sort`,r.`mode_sort`,r.`mtd_cases`,r.`mtd_od_cny`,r.`mtd_arr_cny`,r.`mtd_cash_cny`,r.`yesterday_cash_cny`,r.`total_workdays`,r.`elapsed_workdays`,r.`remaining_workdays`,r.`workday_baseline_mtd_target_cny`,r.`workday_uplift_mtd_target_cny`,r.`workday_baseline_attainment`,r.`workday_uplift_attainment`,r.`workday_uplift_gap_cny`,r.`needed_per_remaining_workday_cny`,r.`baseline_target_cny`,r.`uplift_target_cny`,r.`baseline_attainment`,r.`uplift_attainment`,r.`baseline_remaining_cny`,r.`uplift_remaining_cny`,r.`linear_baseline_pace`,r.`linear_uplift_pace`,r.`needed_daily_cash_cny`,r.`mtd_operating_rate`,r.`mtd_operating_arr_rate`,r.`fullmonth_baseline_od_rate`,r.`fullmonth_uplift_od_rate`,r.`fullmonth_baseline_arr_rate`,r.`fullmonth_uplift_arr_rate`,r.`prior_same_cases`,r.`prior_same_od_cny`,r.`prior_same_cash_cny`,r.`prior_same_operating_rate`,r.`same_period_cash_change`,r.`same_period_od_change`,r.`same_period_cases_change`,r.`prior_month_same_day_cash_share`,r.`curve_baseline_reference_cny`,r.`curve_uplift_reference_cny`,r.`curve_uplift_attainment_reference`,r.`first_cohort_cash_cny`,r.`first_cohort_rate`,r.`cohort_paid_cases`,r.`first_cohort_paid_case_rate`,r.`operating_vs_cohort_cash_gap_cny`,r.`prior_month_mission_cash_cny`,r.`yesterday_onhand`,r.`average_time_weighted_onhand`,r.`added_assets`,r.`cross_mode_cases`,r.`arr_pending`,r.`prior_principal_pending_cases`,r.`fullmonth_forecast_cases`,r.`fullmonth_forecast_od_cny`,r.`fullmonth_forecast_arr_cny`,r.`monthly_baseline_net_target_cny`,r.`monthly_uplift_net_target_cny`,r.`scope_note`
FROM dm_tmp.maxyu_id_long_monitor_main r JOIN ready p ON r.report_month=p.report_month AND r.data_as_of=p.data_as_of AND r.run_id=p.run_id
WHERE r.report_month=CAST(DATE_TRUNC('month',DATE_SUB(CURRENT_DATE(),INTERVAL 1 DAY)) AS DATE)
